 routes.forEach(route=>{let future=route.items.filter(x=>!x.locked),best=simulateFuture(route,future,operational);for(let i=0;i<future.length-1;i++){const candidate=[...future];[candidate[i],candidate[i+1]]=[candidate[i+1],candidate[i]];const test=simulateFuture(route,candidate,operational);if(test&&best&&test.distance+0.05<best.distance){future=candidate;best=test;moves++}}if(best){route.items=best.items;route.end=best.end;route.distance=best.distance}});
 for(const source of routes){const movable=source.items.filter(x=>!x.locked);for(const item of movable.slice(-1)){for(const target of routes){if(target===source||!compatible(item,target.engineer))continue;const sourceFuture=source.items.filter(x=>!x.locked&&x.id!==item.id),targetFuture=[...target.items.filter(x=>!x.locked),item],a=simulateFuture(source,sourceFuture,operational),b=simulateFuture(target,targetFuture,operational);if(a&&b&&a.distance+b.distance+0.05<source.distance+target.distance){source.items=a.items;source.end=a.end;source.distance=a.distance;target.items=b.items;target.end=b.end;target.distance=b.distance;moves++;break}}}}
 let bestSwap=null;for(let ai=0;ai<routes.length;ai++)for(let bi=ai+1;bi<routes.length;bi++){const aRoute=routes[ai],bRoute=routes[bi],aFuture=aRoute.items.filter(x=>!x.locked),bFuture=bRoute.items.filter(x=>!x.locked);for(let i=0;i<aFuture.length;i++)for(let j=0;j<bFuture.length;j++){const aItem=aFuture[i],bItem=bFuture[j];if(!compatible(bItem,aRoute.engineer)||!compatible(aItem,bRoute.engineer))continue;const nextA=[...aFuture],nextB=[...bFuture];nextA[i]=bItem;nextB[j]=aItem;const a=simulateFuture(aRoute,nextA,operational),b=simulateFuture(bRoute,nextB,operational);if(!a||!b)continue;const gain=aRoute.distance+bRoute.distance-a.distance-b.distance;if(gain>.05&&(!bestSwap||gain>bestSwap.gain))bestSwap={aRoute,bRoute,a,b,gain}}}if(bestSwap){bestSwap.aRoute.items=bestSwap.a.items;bestSwap.aRoute.end=bestSwap.a.end;bestSwap.aRoute.distance=bestSwap.a.distance;bestSwap.bRoute.items=bestSwap.b.items;bestSwap.bRoute.end=bestSwap.b.end;bestSwap.bRoute.distance=bestSwap.b.distance;moves++}
