function planBaseline(requests,operational=false){const now=minutes(state.currentTime),routes=state.engineers.map(e=>({engineer:e,items:[],end:operational?Math.max(now,minutes(e.shift[0])):minutes(e.shift[0]),distance:0}));let unassigned=0;[...requests].sort((a,b)=>minutes(a.start)-minutes(b.start)||basePriority(b)-basePriority(a)).forEach(req=>{let choice=null;for(const route of routes){choice=choicesFor(req,[route])[0];if(choice)break}if(!choice){unassigned++;return}commitChoice({...req,K:criticality(req,state.engineers.filter(e=>compatible(req,e)).length)},[choice])});return {...summarizePlan(routes,requests.length-unassigned),routes}}
