function parseCSV(text){const sep=(text.split('\n')[0].match(/;/g)||[]).length>(text.split('\n')[0].match(/,/g)||[]).length?';':',';const rows=text.replace(/^\uFEFF/,'').split(/\r?\n/).filter(Boolean).map(line=>{let arr=[],s='',q=false;for(let i=0;i<line.length;i++){const c=line[i];if(c==='"')q=!q;else if(c===sep&&!q){arr.push(s);s=''}else s+=c}arr.push(s);return arr});const h=rows.shift().map(x=>x.trim());return rows.map(r=>Object.fromEntries(h.map((k,i)=>[k,r[i]?.trim()||''])))}
