function normFor(type){const s=String(type).toLowerCase();if(s.includes('авари'))return 100;if(s.includes('дозаказ'))return 40;if(s.includes('локаль')||s.includes('линк')||s.includes('ремонт'))return 50;return 90}
async function rowsFromFile(file){if(file.name.endsWith('.json'))return JSON.parse(await file.text());if(file.name.match(/\.xlsx?$/i)){if(!window.XLSX)throw Error('Модуль XLSX ещё загружается. Повторите через несколько секунд.');const data=await file.arrayBuffer();const wb=XLSX.read(data,{type:'array'});const preferred=wb.SheetNames.find(n=>/исход|заяв|инжен/i.test(n))||wb.SheetNames[0];return XLSX.utils.sheet_to_json(wb.Sheets[preferred],{defval:''})}return parseCSV(await file.text())}
async function handleFile(kind,file){try{const rows=await rowsFromFile(file);if(kind==='requests'){const report=qualityGateRequests(rows);if(!report.accepted.length)throw Error(`Файл отклонён: ${report.rejected[0]||'нет корректных строк'}`);state.requests=report.accepted;state.qualityReport={accepted:report.accepted.length,rejected:report.rejected};state.newRequests=0;document.querySelector('#requestsMeta').textContent=`${state.requests.length} принято · ${report.rejected.length} отклонено · ${file.name}`}else{const accepted=[],rejected=[];rows.forEach((x,i)=>{const name=x['Имя']||x.name||x['Инженер']||'',skills=String(x['Навыки']||x.skills||'').split(/[,|;]/).map(s=>s.trim()).filter(Boolean),shift=[String(x['Начало смены']||x.shift_start||'').slice(-5),String(x['Конец смены']||x.shift_end||'').slice(-5)];if(!name||!skills.length||!validTime(shift[0])||!validTime(shift[1])||minutes(shift[0])>=minutes(shift[1])){rejected.push(`строка ${i+2}: имя, навыки или смена заполнены неверно`);return}accepted.push({id:x.ID||x.id||`e${i+1}`,name,skills,transport:x['Транспорт']||x.transport||'Автомобиль',shift,start:x['Стартовая точка']||'',coords:[55.735+(i%3)*.005,37.68+(i%4)*.006],delay:[0,0,0,0,0,0],available:!/нет|недоступ/i.test(x['Доступность']||''),reserve:/резерв/i.test(x['Доступность']||'')})});if(!accepted.length)throw Error(`Файл отклонён: ${rejected[0]||'нет корректных строк'}`);state.engineers=accepted;state.qualityReport={accepted:accepted.length,rejected};document.querySelector('#engineersMeta').textContent=`${accepted.length} принято · ${rejected.length} отклонено · ${file.name}`}await calculatePlan('initial');toast(`Файл «${file.name}»: принято ${state.qualityReport.accepted}, отклонено ${state.qualityReport.rejected.length}`)}catch(e){toast(e.message||'Не удалось прочитать файл')}}
['requests','engineers'].forEach(kind=>document.querySelector(`#${kind}File`).addEventListener('change',e=>e.target.files[0]&&handleFile(kind,e.target.files[0])));
async function maybeAutoReplan(){const maxDelay=Math.max(...state.engineers.map(e=>e.delay.at(-1)||0));if(state.auto&&maxDelay>state.threshold){await calculatePlan('operational');state.planVersion++;toast(`Фактическое отставание ${maxDelay} мин превысило порог. Пересчитаны только будущие работы`)}}
