document.querySelector('#stressTestBtn').onclick=async()=>{
 const before=summarizePlan(state.routes,state.requests.length-state.unassigned.length);state.currentTime='12:20';document.querySelector('#currentTime').value='12:20';state.routes.flatMap(r=>r.items).filter(x=>x.planEnd<=minutes(state.currentTime)).forEach(item=>{const req=state.requests.find(r=>r.id===item.id);if(req){req.executionStatus='completed';req.actualTime=fmt(item.planEnd)}});const unavailable=state.engineers.find(e=>e.id==='e5')||state.engineers.find(e=>e.skills.includes('FTTB'));unavailable.available=false;if(!state.requests.some(r=>r.id==='P1')){state.requests.push({id:'P1',bk:'Глобальная проблема',type:'Авария P1',start:'12:25',end:'14:30',zone:'Нижегородский',address:'ул. Смирновская, 18',skill:'FTTB',transport:'Автомобиль',duration:100,isNew:true,executionStatus:'planned',actualTime:''});state.newRequests++}await calculatePlan('operational');const after=summarizePlan(state.routes,state.requests.length-state.unassigned.length),p1Route=state.routes.find(r=>r.items.some(x=>x.id==='P1')),p1=p1Route?.items.find(x=>x.id==='P1');state.stressResult={before,after};document.querySelector('#stressBody').innerHTML=`<p class="dialog-intro">Сценарий использует текущие заявки, ограничения и дорожную матрицу. Никакие KPI не заданы заранее.</p><div class="stress-flow"><article class="stress-step"><strong>До · 12:20</strong>${before.assigned} заявок распределено<br>${Math.round(before.distance)} км<br>${before.used} инженеров</article><span class="stress-arrow">→</span><article class="stress-step"><strong>Событие</strong>${esc(unavailable.name)} снят с линии<br>Получена авария #P1<br>Навык: FTTB</article><span class="stress-arrow">→</span><article class="stress-step"><strong>После</strong>${p1Route?`#P1 → ${esc(p1Route.engineer.name)}<br>${fmt(p1.planStart)}–${fmt(p1.planEnd)}<br>${esc(p1.selectionReason)}`:'#P1 не распределена: нет допустимой вставки'}</article></div><div class="stress-kpis"><span>Зафиксировано<b>${state.lastLockedCount}</b></span><span>Распределено<b>${after.assigned}/${state.requests.length}</b></span><span>Пробег<b>${Math.round(after.distance)} км</b></span><span>Hard violations<b>${after.hard}</b></span></div>`;document.querySelector('#stressDialog').showModal();toast('Stress-test выполнен на текущей дорожной матрице')
};
