function fillEngineerSelects(){
 const offlineValue=document.querySelector('#offlineEngineer').value,manualValue=document.querySelector('#manualEngineer').value;
 const opts=state.engineers.map(e=>`<option value="${esc(e.id)}">${esc(e.name)}${e.available===false?' — не на линии':''}</option>`).join('');
 document.querySelector('#offlineEngineer').innerHTML=opts;document.querySelector('#manualEngineer').innerHTML=opts;
 if(state.engineers.some(e=>e.id===offlineValue))document.querySelector('#offlineEngineer').value=offlineValue;if(state.engineers.some(e=>e.id===manualValue))document.querySelector('#manualEngineer').value=manualValue;updateEngineerStatusAction();
}
function updateEngineerStatusAction(){const engineer=state.engineers.find(x=>x.id===document.querySelector('#offlineEngineer').value),button=document.querySelector('#applyCircumstances'),hint=document.querySelector('#engineerStatusHint');if(!engineer)return;if(state.circumstanceMode==='offline'){const returning=engineer.available===false;button.textContent=returning?'Вернуть на линию и перепланировать':'Снять с линии и перепланировать';button.classList.toggle('danger',!returning);button.classList.toggle('primary',returning);hint.textContent=returning?'Сейчас не на линии. Следующее действие вернёт инженера в доступный состав.':'Сейчас на линии. Следующее действие снимет инженера с доступного состава.'}}
function setCircumstanceMode(mode){state.circumstanceMode=mode;document.querySelectorAll('.mode-switch button').forEach(x=>x.classList.toggle('active',x.dataset.mode===mode));document.querySelector('#emergencyFields').hidden=mode!=='emergency';document.querySelector('#offlineFields').hidden=mode!=='offline';document.querySelectorAll('#emergencyFields input,#emergencyFields select').forEach(x=>x.disabled=mode!=='emergency');const button=document.querySelector('#applyCircumstances');if(mode==='emergency'){button.textContent='Внести и перепланировать';button.classList.add('danger');button.classList.remove('primary')}else updateEngineerStatusAction()}
function openCircumstances(){fillEngineerSelects();setCircumstanceMode('emergency');document.querySelector('#circumstancesDialog').showModal()}
document.querySelector('#circumstancesBtn').onclick=openCircumstances;document.querySelector('#newRequestsCard').onclick=e=>{if(e.target.id!=='openNewRequests')openMetricDetails('new')};document.querySelector('#openNewRequests').onclick=e=>{e.stopPropagation();openCircumstances()};
document.querySelectorAll('.mode-switch button').forEach(b=>b.onclick=()=>setCircumstanceMode(b.dataset.mode));document.querySelector('#offlineEngineer').onchange=updateEngineerStatusAction;
document.querySelector('#applyCircumstances').onclick=async e=>{
 if(state.circumstanceMode==='emergency'){const id=document.querySelector('#emergencyId').value.trim();const address=document.querySelector('#emergencyAddress').value.trim();if(!id||!address){e.preventDefault();toast('Заполните номер и адрес заявки');return}if(state.requests.some(r=>r.id===id)){e.preventDefault();toast('Заявка с таким номером уже существует');return}state.requests.push({id,bk:'Глобальная проблема',type:'Авария',start:document.querySelector('#emergencyStart').value,end:document.querySelector('#emergencyEnd').value,zone:document.querySelector('#emergencyZone').value,address,skill:document.querySelector('#emergencySkill').value,transport:document.querySelector('#emergencyTransport').value,duration:100,isNew:true,executionStatus:'planned',actualTime:''});state.newRequests++;await calculatePlan('operational');toast(`Аварийная заявка #${id} добавлена. Фактические работы сохранены`)}
 else{const id=document.querySelector('#offlineEngineer').value;const engineer=state.engineers.find(x=>x.id===id);if(engineer){const returning=engineer.available===false;engineer.available=returning;if(!returning)engineer.reserve=false;await calculatePlan('operational');toast(returning?`${engineer.name}: возвращён на линию, будущая часть плана пересчитана`:`${engineer.name}: снят с линии, будущие заявки перепланированы`)}}
};
function openManualReplan(engineerId){
 const fixed=new Set(state.routes.flatMap(r=>r.items.filter(x=>x.locked||['enroute','started','completed'].includes(x.executionStatus)).map(x=>x.id))),all=[...state.unassigned,...state.requests.filter(x=>!state.unassigned.some(u=>u.id===x.id)&&!fixed.has(x.id))];document.querySelector('#manualRequest').innerHTML=all.map(r=>`<option value="${esc(r.id)}">#${esc(r.id)} · ${esc(r.type)}</option>`).join('');fillEngineerSelects();if(engineerId)document.querySelector('#manualEngineer').value=engineerId;updateReplanImpact();document.querySelector('#manualReplanDialog').showModal();
}
function updateReplanImpact(){
 const req=state.requests.find(r=>r.id===document.querySelector('#manualRequest').value),engineer=state.engineers.find(e=>e.id===document.querySelector('#manualEngineer').value),start=minutes(document.querySelector('#manualStart').value),box=document.querySelector('#replanImpact');if(!req||!engineer){box.innerHTML='Выберите заявку и инженера.';return}
 const target=state.routes.find(r=>r.engineer.id===engineer.id),baseline=state.routes.find(r=>r.items.some(x=>x.id===req.id)),finish=start+req.duration,overlaps=(target?.items||[]).filter(x=>x.id!==req.id&&start<x.planEnd&&x.planStart<finish),hard=[];
 const incompat=incompatibility(req,engineer);if(incompat)hard.push(incompat);if(start<minutes(req.start)||finish>minutes(req.end))hard.push(`интервал ${fmt(start)}–${fmt(finish)} вне окна ${req.start}–${req.end}`);if(start<minutes(engineer.shift[0])||finish>minutes(engineer.shift[1]))hard.push('работа вне смены');state.manualHardIssues=hard;state.manualOverlaps=overlaps;
 const change=baseline&&baseline.engineer.id!==engineer.id?`Исполнитель изменится: ${baseline.engineer.name} → ${engineer.name}`:'Исполнитель не изменится';const distanceDelta=baseline&&baseline.engineer.id===engineer.id?0:Math.max(3,Math.round((target?.distance||0)*.12));
 const issues=[...hard.map(x=>'Блокирующее ограничение: '+x),...overlaps.map(x=>`Наложение с #${x.id} ${fmt(x.planStart)}–${fmt(x.planEnd)}`)];box.classList.toggle('risk',issues.length>0);box.innerHTML=`<strong>Сравнение с оптимальным планом</strong><div>${esc(change)}. Оценка изменения пробега: ${distanceDelta?'+':''}${distanceDelta} км. Свободный ресурс уменьшится на ${formatDuration(req.duration)}.</div>${issues.length?`<ul>${issues.map(x=>'<li>'+esc(x)+'</li>').join('')}</ul>`:'<div style="margin-top:5px;color:#178a5a">Новых рисков и ухудшений не обнаружено.</div>'}${hard.length?'<div class="audit-note"><strong>Сохранение заблокировано:</strong> hard constraints нельзя обойти вручную.</div>':''}`;
}
document.querySelector('#manualReplanFromPlan').onclick=()=>{const id=state.selectedEngineerId;document.querySelector('#engineerPlanDialog').close();openManualReplan(id)};
['manualRequest','manualEngineer','manualStart'].forEach(id=>document.querySelector('#'+id).addEventListener('change',updateReplanImpact));document.querySelector('#allowOverlap').onchange=e=>{document.querySelector('#overrideReasonField').hidden=!e.target.checked;updateReplanImpact()};
document.querySelector('#manualReplanForm').onsubmit=e=>{
 const requestId=document.querySelector('#manualRequest').value,engineerId=document.querySelector('#manualEngineer').value,start=minutes(document.querySelector('#manualStart').value),allow=document.querySelector('#allowOverlap').checked;
 const req=state.requests.find(r=>r.id===requestId),target=state.routes.find(r=>r.engineer.id===engineerId);if(!req||!target)return;
 const finish=start+req.duration,overlap=target.items.some(x=>x.id!==requestId&&start<x.planEnd&&x.planStart<finish),reason=document.querySelector('#overrideReason').value.trim();if(state.manualHardIssues?.length){e.preventDefault();toast('Сохранение заблокировано: нарушены hard constraints');return}
 if(overlap&&!allow){e.preventDefault();toast('Есть пересечение. Выберите другое время или разрешите наложение.');return}
 if(overlap&&reason.length<5){e.preventDefault();toast('Укажите причину исключения для журнала действий');return}state.routes.forEach(r=>r.items=r.items.filter(x=>x.id!==requestId));target.items.push({...req,planStart:start,planEnd:finish,travel:0,travelKm:0,manual:true,selectionReason:'Ручная корректировка диспетчера'+(reason?`: ${reason}`:'')});target.items.sort((a,b)=>a.planStart-b.planStart);target.manualOverload=overlap&&allow;state.unassigned=state.unassigned.filter(r=>r.id!==requestId);state.auditLog.push({time:state.currentTime,action:`#${requestId} → ${target.engineer.name} ${fmt(start)}${reason?' · '+reason:''}`});renderAll();toast(overlap?'Исключение записано в журнал; перегрузка обновлена':'Ручная корректировка применена');
};
function registerTools(){const mc=document.modelContext;if(!mc?.registerTool)return;mc.registerTool({name:'configure_replanning_trigger',title:'Настроить автопересчёт',description:'Включает или выключает автопересчёт и задаёт порог накопленного отставания.',inputSchema:{type:'object',properties:{enabled:{type:'boolean'},minutes:{type:'number',minimum:1,maximum:180}},required:['enabled','minutes'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:({enabled,minutes})=>{state.auto=enabled;state.threshold=minutes;document.querySelector('#autoTrigger').checked=enabled;document.querySelector('#threshold').value=minutes;renderChart();return{enabled,threshold_minutes:minutes}}});mc.registerTool({name:'run_manual_replanning',title:'Перепланировать маршруты',description:'Пересчитывает незавершённую часть смены.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:()=>{schedule('operational');state.planVersion++;return{version:state.planVersion,assigned:state.requests.length-state.unassigned.length,unassigned:state.unassigned.length,locked:state.lastLockedCount}}})}
